import React, { useState } from "react";
import "./SearchBar.css";
import ClickAwayListener from '@mui/material/ClickAwayListener';

const SearchBar = () => {
 
  const products = [
    {
      id: "1",
      name: "Product 1",
      price: 1000,
      img: require("../images/mug.webp"),
    },
    {
      id: "2",
      name: "Product 2",
      price: 1000,
      img: require("../images/mug.webp"),
    },
    {
      id: "3",
      name: "Product 3",
      price: 1000,
      img: require("../images/mug.webp"),
    },
    {
      id: "4",
      name: "Product 4",
      price: 1000,
      img: require("../images/mug.webp"),
    },
  ];

  const [searchTerm, setSearchTerm] = useState("");
  const [filteredProducts, setFilteredProducts] = useState([]);
  const [open, setOpen] = useState(false);
  const searchItemDetails = (product) => {
    console.log(product.id);
  };
  const searchItemClick = (product) => {
    alert(`Product Details: ${product.name} - ${product.price}`); 
    setOpen(false); // Close results after clicking
    setSearchTerm(""); // Clear search term after clicking
  };
  const handleClickAway = () => {
    setOpen(false); // Close results when clicking away
    setSearchTerm(""); // Clear search term when clicking away
  };

  const searchHandler = (e) => {
    const value = e.target.value;

    setSearchTerm(value);
    setOpen(value.length > 0); // Show results if there's a search term

    console.log(searchTerm);
    if (value) {
      const filtered = products.filter((products) =>
        products.name.toLowerCase().includes(value.toLowerCase())
      );
      setFilteredProducts(filtered);
    } else {
      setFilteredProducts([]);
    }
  };
  return (
    <ClickAwayListener onClickAway={handleClickAway}>
    <div>
      <input
        className="search-input"
        type="text"
        placeholder="Search here..."
        value={searchTerm}
        onChange={searchHandler}
      />
      {open && (
          <div className="search-results">
            {filteredProducts.map((product) => (
              <div
                className="product-list-card"
                key={product.id}
                onClick={() => searchItemClick(product)}
              >
                <div className="product-img-div">
                  <img src={product.img} alt="Product" className="w-100" />
                </div>
                <div className="product-name">
                  <h3>{product.name}</h3>
                </div>
                <div className="product-price">
                  <h6>{product.price}</h6>
                </div>
              </div>
            ))}
          </div>
        )}
    </div>
    </ClickAwayListener>
  );
};

export default SearchBar;
